HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
RD = '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/DENSE_GENERIC_PAC_INTEGRATION_1'; PGM = '/Users/adis/Workspace/pgm'
USR = '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/UNIFIED_SCHEDULING_REVISION_1/TRIAL_MANIFEST.json'; R22B = '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/BLOCKRES_2026-11-19/round22b/PRESERVATION_MANIFEST.json'; R22C = '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/BLOCKRES_2026-11-19/round22c/G4_MANIFEST.json'
def sha(p): return hashlib.sha256(open(p, 'rb').read()).hexdigest()
def git(*a): return subprocess.check_output(['git', '-C', PGM] + list(a)).decode().strip()
LONG_NAMES = ['dg_n32_c2_er50_two', 'dg_n32_c4_er50_two', 'dg_n64_c2_er50_two', 'dg_n64_c4_er50_two']

def verify(tasks):
    for t in tasks:
        assert os.path.exists(t['model']), t['model']; assert sha(t['model']) == t['model_sha256'], t['name']
        ev = t.get('evidence') or (t['model'] + '.evid'); assert sha(ev) == t['evid_sha256'], t['name']; t['verified_now'] = True
    return tasks

